const PLAYER_BY_ID = new Map(PLAYERS.map((p) => [p.id, p]));
PLAYER_BY_ID.set(BONUS_PLAYER.id, BONUS_PLAYER);

export function getPlayerById(id) {
  return PLAYER_BY_ID.get(id) || null;
}
